.map-hero .map-outline ul { margin: 0; padding-left: 22px; }
.map-hero .map-outline li { overflow-wrap: anywhere; color: var(--ink); }
.map-hero .map-outline li > span { overflow-wrap: anywhere; }
.result-columns { display: grid; grid-template-columns: 1fr 1fr; gap: 0 40px; }
.sec { background: transparent; border: 0; border-top: 1px solid var(--rule); border-radius: 0; padding: 16px 0; margin: 0; }
.sec h3 { font-size: 15px; letter-spacing: 2px; margin: 0 0 10px; color: var(--ink-dim); font-weight: 400; }
.sec p, .sec li { line-height: 1.8; overflow-wrap: anywhere; color: var(--ink); font-size: 16px; }
.sec ul { margin: 0; padding-left: 20px; }
.sec ul.marked-list { list-style: none; padding-left: 2px; }
.marked-item { list-style: none; }
.item-marker { display: inline-block; min-width: 20px; color: var(--ink-dim); }
.marker-decision { font-size: 13px; }
.sec details { margin-top: 6px; }
.sec a { overflow-wrap: anywhere; color: var(--ink); }
.draft-head { display: flex; gap: 12px; align-items: baseline; justify-content: space-between; }
.draft-head h3 { margin-bottom: 4px; }
.draft-copy { flex: 0 0 auto; }
.draft-instruction { color: var(--ink-dim); font-size: 15px; margin: 0 0 10px; }
.draft-running { color: var(--ink-dim); }
.draft-body {
  white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.85; font-size: 17px; color: var(--ink);
  background: #fffdf6; border: 1px solid var(--rule); padding: 18px; 
}
.evidence-btn {
  background: transparent; border: 0; border-radius: 0; padding: 0; margin: 0; font-size: inherit;
  line-height: inherit; color: var(--ink); text-align: left; cursor: pointer;
}
.evidence-tag {
  color: var(--ink-dim); font-size: 15px; margin-left: 8px;
  text-decoration: underline dotted; text-underline-offset: 3px; white-space: nowrap;
}
.evidence-arrow { display: inline-block; color: var(--ink-dim); margin-left: 4px; transition: transform 0.2s ease; }
.evidence-btn.open .evidence-arrow { transform: rotate(90deg); }
.evidence-quote {
  color: var(--ink-dim); line-height: 1.7; margin: 6px 0 4px 12px; padding-left: 12px;
  border-left: 2px solid var(--rule); overflow-wrap: anywhere; font-size: 16px;
}
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}
.transcript-sec summary { cursor: pointer; color: var(--ink-dim); font-size: 15px; line-height: 1.8; }
.transcript-sec ul { margin-top: 10px; }
.result-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; border-top: 1px solid var(--rule); padding-top: 20px; margin-top: 8px; }
.result-actions .quiet-btn, .result-actions .buttonlike { color: var(--ink-dim); }
.result-actions button.primary.ink-btn {
  width: auto; height: auto; margin: 0; border-radius: 999px; padding: 12px 22px;
  background: var(--ink); color: var(--paper); font-size: 16px; letter-spacing: 0; box-shadow: none;
}
.empty-line { color: var(--ink-dim); line-height: 1.8; font-size: 16px; }
@media (max-width: 800px) {
  .start-columns { grid-template-columns: 1fr; gap: 20px; }
  .start-page { padding-top: 36px; }
  .start-headline { font-size: 32px; }
  .how-sheet { width: 100%; }
}
@media (max-height: 800px) and (min-width: 801px) {
  .start-page { padding-top: 12px; padding-bottom: 20px; }
  .brand { margin-bottom: 10px; }
  .start-headline { font-size: 32px; margin-bottom: 8px; }
  .start-subline { margin-bottom: 12px; line-height: 1.5; }
  button.primary, .lights-off { margin-top: 12px; padding: 11px 26px; }
  .how-sheet img { aspect-ratio: 2.1; }
  .check { margin-top: 8px; }
}
@media (max-width: 640px) { .result-columns { grid-template-columns: 1fr; } }
@media (prefers-reduced-motion: reduce) {
  .mic-btn.recording { animation: none; }
  #page-black { animation: none; }
  .result-page.light-fade { animation: none; }
  .hint { transition: none; }
  .poster-placeholder { animation: none; }
  .pending-line { animation: none; }
  .evidence-arrow { transition: none; }
}
